test("CONCURRENT signalError calls still yield exactly one error", async () => {
  // The three emitters are not sequenced with respect to each other:
  // `sse-client.ts`'s outer catch can fire while `worker.ts`'s branch is
  // still awaiting its POST. A latch that is CHECKED before an await but SET
  // after it lets both callers pass the check, so both deliver — the exact
  // duplicate this latch exists to prevent.
  const transport = new HttpWorkerTransport(baseConfig);

  // Hold every POST open until both callers are provably in flight, so the
  // interleaving is deterministic rather than timing-dependent.
  let releaseFetch: () => void = () => {};
  const fetchGate = new Promise<void>((resolve) => {
    releaseFetch = resolve;
  });
  globalThis.fetch = (async (
    ...args: Parameters<typeof globalThis.fetch>
  ) => {
    const init = args[1];
    if (init?.body) sentPayloads.push(JSON.parse(init.body as string));
    await fetchGate;
    return new Response(null, { status: 200 });
  }) as typeof globalThis.fetch;

  const first = transport.signalError(new Error("first"), "PROVIDER_AUTH");
  const second = transport.signalError(new Error("second"));
  releaseFetch();
  await Promise.all([first, second]);

  const errors = errorPayloads();
  expect(errors).toHaveLength(1);
  expect(errors[0].error).toBe("first");
  expect(errors[0].errorCode).toBe("PROVIDER_AUTH");
});

test("a fresh transport (next turn) can signal an error again", async () => {

private errorSignalled = false;
/**
 * The in-flight terminal-error POST, if one is running. The emitters are not
 * sequenced with respect to each other, so a plain boolean checked before an
 * `await` and set after it lets two concurrent callers both pass the check
 * and both deliver. Callers that arrive during a delivery await THIS promise
 * instead of starting their own; it is cleared on rejection so a failed
 * delivery still leaves the turn retryable.
 */
private errorDelivery?: Promise<void>;

