  // URL itself).
  const code = toAgentErrorCode(payload.errorCode);
  const spec = code ? AGENT_ERRORS[code] : undefined;
  if (spec?.silent) {
    // Silent codes (SESSION_TIMEOUT) are retried and must not surface.
    await this.resolveWatcherRunsFromPayload(payload, {
      ok: false,
      error: "agent error",
    });
    return;
  }
  const errorText = spec?.message ?? payload.error;

  const errorEvent = {
    type: "error",
    error: errorText,
    errorCode: code,
    errorContext: payload.errorContext,
    messageId: payload.messageId,
    timestamp: payload.timestamp || Date.now(),
  };

  // Keep the legacy `error` event for existing consumers, but also emit a
  // non-reserved event name for browsers: native EventSource treats `error`
  // specially and may not expose server-sent event data to addEventListener.
  this.sseManager.broadcast(sessionId, "error", errorEvent);
  this.sseManager.broadcast(sessionId, "agent-error", errorEvent);

  logger.error(`Broadcast error to session ${sessionId}: ${errorText}`);

  await this.resolveWatcherRunsFromPayload(payload, {
    ok: false,
    error: typeof errorText === "string" ? errorText : "agent error",
  });
}

/**
 * Resolve any watcher runs whose dispatched messageId matches the terminal
 * event. Checks both the immediate messageId and processedMessageIds since
 * a single turn can batch-process multiple messages. Durable and replica-
 * safe: keyed on runs.dispatched_message_id, idempotent via the active-
 * status guard, so it's correct on whichever replica claims the row.
 */
private async resolveWatcherRunsFromPayload(
  payload: ThreadResponsePayload,
  result: { ok: true } | { ok: false; error: string }
): Promise<void> {
  const ids = new Set<string>();
  if (payload.messageId) ids.add(payload.messageId);
  for (const id of payload.processedMessageIds ?? []) {
    if (id) ids.add(id);
  }
  try {
    await resolveWatcherRunsByMessageIds(ids, result);
  } catch (error) {
    logger.error("Failed to resolve watcher runs from terminal API payload", {
      error,
    });
  }
}

 *
 * The body is deliberately thin: for provider errors the catalog has no text, so
 * we relay the provider's OWN message verbatim (it already says the useful thing
 * — the reset time, the bad model id). For errors we synthesize (worker/config),
 * the catalog carries the text. The code's only job is to pick the CTA *kind*;
 * this resolves that kind to a concrete URL via the matching injected resolver,
 * so "connect a provider" and "pick a model" land on their own pages instead of
 * collapsing to one.
 */
export async function renderAgentError(
  code: AgentErrorCode,
  providerMessage: string | undefined,
  resolvers: AgentErrorCtaResolvers
): Promise<RenderedAgentError> {
  const spec = AGENT_ERRORS[code];
  const text = spec.message ?? providerMessage ?? '';
  let ctaUrl: string | null = null;
  const resolve =
    spec.cta === 'agent-settings' ||
    spec.cta === 'provider-connect' ||
    spec.cta === 'provider-management'
      ? resolvers[spec.cta]
      : undefined;
  if (resolve) {
    ctaUrl = await resolve().catch(() => null);
  }
  return {
    text,
    ctaUrl,
    ctaLabel: spec.ctaLabel,
    silent: spec.silent ?? false,
  };
}

