		ORDER BY slug
	`) as Array<Omit<RawInferenceProviderRow, "organization_id" | "api_key_ref">>;
	return rows.map((r) => ({
		id: Number(r.id),
		slug: r.slug,
		kind: r.kind,
		displayName: r.display_name,
		capabilities: r.capabilities ?? {},
		hasCustomUpstream: r.has_custom_upstream,
